import{_ as a,c as d,o as e,b0 as r}from"./chunks/framework.C5ev1SXp.js";const o="/scm-docs/assets/lan-devices.BCGFPsZ6.svg",q=JSON.parse('{"title":"LV020-交换机路由器与局域网","description":null,"frontmatter":{"title":"LV020-交换机路由器与局域网","date":"2026-10-14T21:56:00.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/advanced-chapter/network-basics/126d628e1bb0169159fefb70","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-14T21:56:00.361Z","fulluuid":"159fefb70a0e4ffe86583a748d21ec82","useduuid":"159fefb70"}},"headers":[],"relativePath":"sdoc/advanced-chapter/network-basics/126d628e1bb0169159fefb70.md","filePath":"sdoc/30-进阶篇/05-网络基础/LV020-交换机路由器与局域网.md","lastUpdated":1792231946000}'),l={name:"sdoc/advanced-chapter/network-basics/126d628e1bb0169159fefb70.md"};function h(n,t,i,s,c,u){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="lv020-交换机路由器与局域网" tabindex="-1">LV020-交换机路由器与局域网 <a class="header-anchor" href="#lv020-交换机路由器与局域网" aria-label="Permalink to &quot;LV020-交换机路由器与局域网&quot;">​</a></h1><h2 id="一、-局域网就是一个广播域" tabindex="-1">一、 局域网就是一个广播域 <a class="header-anchor" href="#一、-局域网就是一个广播域" aria-label="Permalink to &quot;一、 局域网就是一个广播域&quot;">​</a></h2><h3 id="_1-局域网的范围与特征" tabindex="-1">1. 局域网的范围与特征 <a class="header-anchor" href="#_1-局域网的范围与特征" aria-label="Permalink to &quot;1. 局域网的范围与特征&quot;">​</a></h3><p><strong>局域网（LAN）就是&quot;一个广播域&quot;</strong>——在这个范围内，一台设备发出的广播帧，其它设备都能收到。家用场景里，一台交换机（或一台路由器后面的所有有线口）下面的设备，就是一个局域网。</p><p>局域网有几个特点值得记住：</p><ul><li>范围小，通常是一个房间、一层楼、一个办公室；</li><li>里面的设备<strong>共享同一个网段</strong>（所以上一篇讲的按位与判断，在这里起决定作用）；</li><li>局域网内部靠<strong>交换机的 MAC 表</strong>转发，不需要路由器参与。</li></ul><h3 id="_2-为什么-一个网段-一个广播域" tabindex="-1">2. 为什么&quot;一个网段 = 一个广播域&quot; <a class="header-anchor" href="#_2-为什么-一个网段-一个广播域" aria-label="Permalink to &quot;2. 为什么&quot;一个网段 = 一个广播域&quot;&quot;">​</a></h3><p>这条等价关系是理解交换机与路由器分工的关键，先记住结论，理由在本篇第五节与第六节展开：</p><table tabindex="0"><thead><tr><th>设备</th><th>能不能转发数据</th><th>能不能隔离广播</th></tr></thead><tbody><tr><td>集线器</td><td>能（泛洪）</td><td>不能</td></tr><tr><td>交换机</td><td>能（按 MAC 表）</td><td><strong>不能</strong></td></tr><tr><td>路由器</td><td>能（按路由表）</td><td><strong>能</strong></td></tr></tbody></table><p>交换机不隔离广播，所以<strong>同一个交换机下的所有设备仍然属于同一个广播域、同一个网段</strong>。要让广播停下来，只能靠路由器（或者在交换机上划分 VLAN，那属于更进一步的用法）。</p><p>这解释了本实验里一个容易困惑的点：<strong>为什么板子必须和 PC 配成同网段？</strong> 因为直连与同交换机都属于同一个广播域，而同一个广播域里就是同一个网段——网段就是按广播域划的。</p><h2 id="二、-三种接法与它们的差别" tabindex="-1">二、 三种接法与它们的差别 <a class="header-anchor" href="#二、-三种接法与它们的差别" aria-label="Permalink to &quot;二、 三种接法与它们的差别&quot;">​</a></h2><h3 id="_1-直连、交换机、路由器" tabindex="-1">1. 直连、交换机、路由器 <a class="header-anchor" href="#_1-直连、交换机、路由器" aria-label="Permalink to &quot;1. 直连、交换机、路由器&quot;">​</a></h3><p>本实验最常遇到的三种物理接法，它们的差别<strong>不在物理层，而在&quot;要不要跨网段&quot;</strong>：</p><table tabindex="0"><thead><tr><th>接法</th><th>板子与 PC 是否同网段</th><th>需要网关吗</th><th>能不能上网</th></tr></thead><tbody><tr><td>网线直连</td><td>必须自己配成同网段</td><td>不需要</td><td>不能</td></tr><tr><td>都接在同一台交换机</td><td>必须自己配成同网段</td><td>不需要</td><td>不能（除非上面还接了路由器）</td></tr><tr><td>都接在同一台路由器下</td><td>由路由器分配，通常同网段</td><td>若要出网则需要</td><td>可以</td></tr></tbody></table><img src="'+o+'" alt="直连、交换机与路由器三种接法及其转发依据"><p>本实验用的是第一种或第二种，所以板子与 PC 的 IP 必须<strong>手工配成同网段</strong>（<code>192.168.16.30</code> 与 <code>192.168.16.100</code>）。</p><h3 id="_2-三种接法的排查重点" tabindex="-1">2. 三种接法的排查重点 <a class="header-anchor" href="#_2-三种接法的排查重点" aria-label="Permalink to &quot;2. 三种接法的排查重点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接法</th><th>排查重点</th></tr></thead><tbody><tr><td>网线直连</td><td>网口灯是否亮；两端 IP 与掩码是否同网段；是否配了不存在的网关</td></tr><tr><td>经交换机</td><td>以上全部，外加：交换机是否通电、端口是否协商成功、有没有把两个口接成环</td></tr><tr><td>经路由器</td><td>板子是否拿到（或配了）路由器网段的地址；网关是否填的是路由器地址</td></tr></tbody></table><p>顺带说清一个常见误解：<strong>&quot;接上网线就能上网&quot;是不成立的</strong>。上网需要路由器、需要 NAT、需要 DNS，而本实验的 Bootloader 只实现了 IP/ICMP/TCP/UDP/ARP 这一小块，既没有 DHCP 也没有 DNS，所以它的目标就是&quot;在同一局域网内被 PC 找到&quot;，而不是上网。</p><h2 id="三、-集线器与交换机" tabindex="-1">三、 集线器与交换机 <a class="header-anchor" href="#三、-集线器与交换机" aria-label="Permalink to &quot;三、 集线器与交换机&quot;">​</a></h2><h3 id="_1-差在-认不认识-mac" tabindex="-1">1. 差在&quot;认不认识 MAC&quot; <a class="header-anchor" href="#_1-差在-认不认识-mac" aria-label="Permalink to &quot;1. 差在&quot;认不认识 MAC&quot;&quot;">​</a></h3><p>同样是&quot;把几台设备连在一起&quot;，集线器和交换机的差别很大：</p><table tabindex="0"><thead><tr><th>对比项</th><th>集线器（Hub）</th><th>交换机（Switch）</th></tr></thead><tbody><tr><td>工作层次</td><td>物理层</td><td>数据链路层</td></tr><tr><td>转发方式</td><td>从任意口收到的数据<strong>向所有其它口泛洪</strong></td><td>按 MAC 地址表<strong>只从对应口发出</strong></td></tr><tr><td>带宽</td><td>所有口共享</td><td>每个口独享</td></tr><tr><td>冲突</td><td>会冲突，需要 CSMA/CD</td><td>基本没有冲突</td></tr></tbody></table><h3 id="_2-集线器没白学-泛洪是它的退化形态" tabindex="-1">2. 集线器没白学：泛洪是它的退化形态 <a class="header-anchor" href="#_2-集线器没白学-泛洪是它的退化形态" aria-label="Permalink to &quot;2. 集线器没白学：泛洪是它的退化形态&quot;">​</a></h3><p>集线器现在基本见不到了，但理解它的存在有个好处：<strong>交换机&quot;查不到就泛洪&quot;的行为，本质上就是退化成了集线器</strong>。</p><p>所以交换机的工作过程可以理解成&quot;先像集线器一样泛洪学习，之后才会精准转发&quot;——这也解释了为什么一个刚上电的交换机头几个包总是泛洪的。</p><h2 id="四、-交换机怎么转发-mac-地址表" tabindex="-1">四、 交换机怎么转发：MAC 地址表 <a class="header-anchor" href="#四、-交换机怎么转发-mac-地址表" aria-label="Permalink to &quot;四、 交换机怎么转发：MAC 地址表&quot;">​</a></h2><p>交换机内部维护一张&quot;MAC 地址 → 端口&quot;的表，动作分学习和转发两步。</p><h3 id="_1-学习-收到帧时看源-mac" tabindex="-1">1. 学习：收到帧时看源 MAC <a class="header-anchor" href="#_1-学习-收到帧时看源-mac" aria-label="Permalink to &quot;1. 学习：收到帧时看源 MAC&quot;">​</a></h3><p>看<strong>源 MAC</strong>，把&quot;这个 MAC 在我的第 N 号口上&quot;记进表里。之后有包要发给它，就知道从哪个口出。</p><p>这个设计的巧妙之处在于：<strong>学习是&quot;顺便&quot;完成的</strong>，不需要任何额外报文。只要这台设备发过一次帧，交换机就记住了它在哪个口。</p><h3 id="_2-转发-决定从哪出时看目的-mac" tabindex="-1">2. 转发：决定从哪出时看目的 MAC <a class="header-anchor" href="#_2-转发-决定从哪出时看目的-mac" aria-label="Permalink to &quot;2. 转发：决定从哪出时看目的 MAC&quot;">​</a></h3><p>看<strong>目的 MAC</strong>，按表决定动作：</p><table tabindex="0"><thead><tr><th>目的 MAC 在表里</th><th>动作</th></tr></thead><tbody><tr><td>在，且不是收到帧的那个口</td><td>从对应口发出（单播）</td></tr><tr><td>在，正好是收到帧的那个口</td><td>丢弃（不需要转发）</td></tr><tr><td>不在表里</td><td><strong>向所有其它口泛洪</strong></td></tr><tr><td>是广播地址 <code>FF:FF:FF:FF:FF:FF</code></td><td>向所有其它口泛洪</td></tr></tbody></table><p>&quot;在，正好是收到帧的那个口&quot;这一行容易被忽略：说明这台设备就在这个口的方向上，没必要再发回去。</p><h3 id="_3-表项老化" tabindex="-1">3. 表项老化 <a class="header-anchor" href="#_3-表项老化" aria-label="Permalink to &quot;3. 表项老化&quot;">​</a></h3><p>表项还有老化时间，长时间不出现的 MAC 会被清除——这点和后面 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb01bacb81dfb86.html">LV030-ARP与MAC地址</a> 里 ARP 缓存的老化是一回事：<strong>两者的存在都是为了&quot;设备会挪位置、地址会换主人&quot;</strong>。</p><h2 id="五、-路由器怎么工作" tabindex="-1">五、 路由器怎么工作 <a class="header-anchor" href="#五、-路由器怎么工作" aria-label="Permalink to &quot;五、 路由器怎么工作&quot;">​</a></h2><h3 id="_1-成为路由器的三个条件" tabindex="-1">1. 成为路由器的三个条件 <a class="header-anchor" href="#_1-成为路由器的三个条件" aria-label="Permalink to &quot;1. 成为路由器的三个条件&quot;">​</a></h3><p><strong>一台设备要算路由器，必须同时满足三个条件：</strong></p><p>（1）至少有两个网络接口。</p><p>（2）两个接口接在<strong>不同的网段</strong>上。</p><p>（3）能在两个网段之间转发数据。</p><p>只有一块网卡的设备，无论装什么系统都当不成路由器。反过来，一台双网卡的 PC 只要开了转发功能，就成了事实上的路由器。</p><h3 id="_2-路由表与转发" tabindex="-1">2. 路由表与转发 <a class="header-anchor" href="#_2-路由表与转发" aria-label="Permalink to &quot;2. 路由表与转发&quot;">​</a></h3><p>路由器的核心是一张<strong>路由表</strong>，每条表项是&quot;目的网络 → 下一跳 / 出口&quot;：</p><table tabindex="0"><thead><tr><th>目的网络</th><th>下一跳</th><th>出口</th></tr></thead><tbody><tr><td>192.168.16.0/24</td><td>直连</td><td>接口 A</td></tr><tr><td>192.168.1.0/24</td><td>192.168.16.1</td><td>接口 A</td></tr><tr><td>0.0.0.0/0（默认路由）</td><td>运营商网关</td><td>接口 B</td></tr></tbody></table><p>转发时的顺序是&quot;最长前缀匹配&quot;：先找最精确的那条，找不到就落到默认路由 <code>0.0.0.0/0</code>。这套机制的完整说明见 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0267db3a1c4e8.html">LV015-网关与跨网段通信</a> 第二节。</p><h3 id="_3-转发时会改什么" tabindex="-1">3. 转发时会改什么 <a class="header-anchor" href="#_3-转发时会改什么" aria-label="Permalink to &quot;3. 转发时会改什么&quot;">​</a></h3><p><strong>这里有一个关键认知</strong>：路由器转发时会<strong>把链路层的帧头整个换掉</strong>——IP 头里的源/目的地址全程不变，而以太网头里的源/目的 MAC 每一跳都会重写（TTL 也会减 1）。</p><p>这就是&quot;MAC 只在一跳内有效&quot;的具体体现，也是 <code>ping</code> 的输出里 <code>TTL</code> 会随着经过的路由器增多而变小的原因。</p><h2 id="六、-小结与参考资料" tabindex="-1">六、 小结与参考资料 <a class="header-anchor" href="#六、-小结与参考资料" aria-label="Permalink to &quot;六、 小结与参考资料&quot;">​</a></h2><h3 id="_1-本篇小结" tabindex="-1">1. 本篇小结 <a class="header-anchor" href="#_1-本篇小结" aria-label="Permalink to &quot;1. 本篇小结&quot;">​</a></h3><ul><li>局域网 = 一个广播域，范围内的设备共享同一网段；网段就是按广播域划分的。</li><li>集线器（物理层泛洪）→ 交换机（链路层按 MAC 表转发）→ 路由器（网络层按路由表转发），能力逐级上升。</li><li>交换机靠&quot;学源 MAC、查目的 MAC&quot;工作，查不到就泛洪；表项会老化。</li><li>只有路由器能隔离广播域，且成为路由器必须满足&quot;两个接口、不同网段、能转发&quot;三个条件。</li><li>路由器转发时只重写链路层帧头与 TTL，IP 头全程不变。</li><li>本实验属于直连或同交换机两种接法，双方必须手工配成同网段，且用不到网关。</li></ul><h3 id="_2-参考资料" tabindex="-1">2. 参考资料 <a class="header-anchor" href="#_2-参考资料" aria-label="Permalink to &quot;2. 参考资料&quot;">​</a></h3><ul><li>实验中的实际连接与排错：<a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5205f2a80bf1e.html">LV020-网络通信实验</a> 第一节、第五节</li><li>网卡驱动与收发路径：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Drivers/BSP/Ethernet/dm9000.c" target="_blank" rel="noreferrer"><code>dm9000.c</code></a></li><li>手册：<a href="https://gitee.com/docs-site/scm-reference-guide/raw/main/30-STM32%E8%B5%84%E6%96%99/10-lwIP/STM32F1%20LWIP%E5%BC%80%E5%8F%91%E6%89%8B%E5%86%8C%28DM9000%E7%89%88%29_V1.1.pdf" target="_blank" rel="noreferrer"><code>STM32F1 LWIP开发手册(DM9000版)_V1.1.pdf</code></a> 第 1.6 节「下载验证」</li></ul><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>',59)])])}const p=a(l,[["render",h]]);export{q as __pageData,p as default};
